-- HALO: check that migrations 0019 to 0023 are all applied correctly. Read only.
-- Generated by scripts/build-apply-bundle.mjs from each migration's own verification query.
-- Expect one row: all_migrations_ok = true and failing = none.

with checks as (
  select '0019' as migration, j.key as check_name, coalesce(j.value::boolean, false) as ok
  from (
    select
        exists (select 1 from pg_attribute
          where attrelid = 'public.recovery_challenges'::regclass
            and attname = 'intent' and not attisdropped) as column_added,
        (select attnotnull from pg_attribute
          where attrelid = 'public.recovery_challenges'::regclass
            and attname = 'intent') as not_null,
        exists (select 1 from pg_constraint
          where conname = 'recovery_challenges_intent_check') as check_added
  ) q, jsonb_each_text(to_jsonb(q)) j
  union all
  select '0020' as migration, j.key as check_name, coalesce(j.value::boolean, false) as ok
  from (
    select
        (select bool_and(c.relrowsecurity) from pg_class c
          where c.oid in ('public.luna_conversations'::regclass,
                          'public.luna_turns'::regclass,
                          'public.luna_runs'::regclass)) as rls_on,
        (select count(*) from pg_policies
          where schemaname = 'public'
            and tablename in ('luna_conversations', 'luna_turns', 'luna_runs')) = 0
          as no_policies,
        not exists (
          select 1 from unnest(array['public.luna_conversations', 'public.luna_turns', 'public.luna_runs']) as t,
                      unnest(array['anon', 'authenticated']) as r
           where has_any_column_privilege(r, t, 'SELECT')
              or has_any_column_privilege(r, t, 'INSERT')
              or has_any_column_privilege(r, t, 'UPDATE')
              or has_table_privilege(r, t, 'DELETE'))
          as no_client_access,
        (select bool_and(has_table_privilege('service_role', t, 'INSERT')
                     and has_table_privilege('service_role', t, 'UPDATE'))
           from unnest(array['public.luna_conversations', 'public.luna_turns', 'public.luna_runs']) as t)
          as service_role_can_write,
        (select count(*) from pg_constraint
          where conrelid in ('public.luna_conversations'::regclass,
                             'public.luna_turns'::regclass,
                             'public.luna_runs'::regclass)
            and contype = 'c') = 10
          as ten_checks
  ) q, jsonb_each_text(to_jsonb(q)) j
  union all
  select '0021' as migration, j.key as check_name, coalesce(j.value::boolean, false) as ok
  from (
    select
        (select relrowsecurity from pg_class
          where oid = 'public.profile_preferences'::regclass) as rls_on,
        (select count(*) from pg_policies
          where schemaname = 'public' and tablename = 'profile_preferences') = 0
          as no_policies,
        not exists (
          select 1 from unnest(array['anon', 'authenticated']) as r
           where has_any_column_privilege(r, 'public.profile_preferences', 'SELECT')
              or has_any_column_privilege(r, 'public.profile_preferences', 'INSERT')
              or has_any_column_privilege(r, 'public.profile_preferences', 'UPDATE')
              or has_table_privilege(r, 'public.profile_preferences', 'DELETE'))
          as no_client_access,
        has_table_privilege('service_role', 'public.profile_preferences', 'INSERT')
          and has_table_privilege('service_role', 'public.profile_preferences', 'UPDATE')
          as service_role_can_write,
        (select count(*) from pg_constraint
          where conrelid = 'public.profile_preferences'::regclass and contype = 'c') = 9
          as nine_checks,
        (select count(*) from pg_attribute
          where attrelid = 'public.profiles'::regclass and attname = 'tenure' and not attisdropped)
        + (select count(*) from pg_attribute
            where attrelid = 'public.alerts'::regclass and not attisdropped
              and attname in ('revision', 'category', 'target_tab', 'target_destination', 'target_learn'))
          = 6 as tenure_and_alert_columns,
        (select count(*) from pg_trigger
          where not tgisinternal
            and tgname in ('profile_preferences_settings_revision', 'profiles_settings_revision',
                           'profiles_tenure_reconcile', 'notification_prefs_settings_revision',
                           'notification_prefs_settings_revision_insert', 'household_bands_settings_revision',
                           'household_bands_settings_revision_insert', 'operations_settings_settled_guard')) = 8
        and has_function_privilege('service_role',
              'public.save_settings(uuid, uuid, int, jsonb, jsonb, jsonb, jsonb, jsonb)', 'EXECUTE')
        and not exists (
          select 1 from unnest(array['anon', 'authenticated']) as r
           where has_function_privilege(r,
                   'public.save_settings(uuid, uuid, int, jsonb, jsonb, jsonb, jsonb, jsonb)', 'EXECUTE'))
          as revision_kept_by_the_database
  ) q, jsonb_each_text(to_jsonb(q)) j
  union all
  select '0022' as migration, j.key as check_name, coalesce(j.value::boolean, false) as ok
  from (
    select
        (select relrowsecurity from pg_class
          where oid = 'public.explore_areas'::regclass) as rls_on,
        (select count(*) from pg_policies
          where schemaname = 'public' and tablename = 'explore_areas') = 0
          as no_policies,
        not exists (
          select 1 from unnest(array['anon', 'authenticated']) as r
           where has_any_column_privilege(r, 'public.explore_areas', 'SELECT')
              or has_any_column_privilege(r, 'public.explore_areas', 'INSERT')
              or has_any_column_privilege(r, 'public.explore_areas', 'UPDATE')
              or has_table_privilege(r, 'public.explore_areas', 'DELETE'))
          as no_client_access,
        has_table_privilege('service_role', 'public.explore_areas', 'INSERT')
          and has_table_privilege('service_role', 'public.explore_areas', 'UPDATE')
          as service_role_can_write,
        (select count(*) from pg_constraint
          where conrelid = 'public.explore_areas'::regclass and contype = 'c') = 4
          as four_checks
  ) q, jsonb_each_text(to_jsonb(q)) j
  union all
  select '0023' as migration, j.key as check_name, coalesce(j.value::boolean, false) as ok
  from (
    select
        (select bool_and(c.relrowsecurity) from pg_class c
          where c.oid in ('public.household_actions'::regclass,
                          'public.household_action_preferences'::regclass,
                          'public.household_action_state'::regclass)) as rls_on,
        (select count(*) from pg_policies
          where schemaname = 'public'
            and tablename in ('household_actions', 'household_action_preferences', 'household_action_state')) = 0
          as no_policies,
        not exists (
          select 1 from unnest(array['anon', 'authenticated']) as r
           cross join unnest(array['public.household_actions', 'public.household_action_preferences',
                                   'public.household_action_state']) as t
           where has_any_column_privilege(r, t, 'SELECT')
              or has_any_column_privilege(r, t, 'INSERT')
              or has_any_column_privilege(r, t, 'UPDATE')
              or has_table_privilege(r, t, 'DELETE'))
          as no_client_access,
        not (has_function_privilege('anon', 'public.read_household_actions(uuid)', 'EXECUTE')
          or has_function_privilege('authenticated', 'public.read_household_actions(uuid)', 'EXECUTE')
          or has_function_privilege('anon', 'public.commit_household_actions(uuid, uuid, bigint, jsonb)', 'EXECUTE')
          or has_function_privilege('authenticated', 'public.commit_household_actions(uuid, uuid, bigint, jsonb)', 'EXECUTE'))
          and has_function_privilege('service_role', 'public.read_household_actions(uuid)', 'EXECUTE')
          and has_function_privilege('service_role', 'public.commit_household_actions(uuid, uuid, bigint, jsonb)', 'EXECUTE')
          as functions_service_role_only,
        exists (select 1 from pg_trigger
          where tgrelid = 'public.operations'::regclass and tgname = 'operations_actions_settled_guard')
          as settled_guard_on,
        (select count(*) from pg_constraint
          where conrelid in ('public.household_actions'::regclass,
                             'public.household_action_preferences'::regclass,
                             'public.household_action_state'::regclass) and contype = 'c') = 10
          as ten_checks
  ) q, jsonb_each_text(to_jsonb(q)) j
)
select bool_and(ok) as all_migrations_ok,
       count(*) as checks_run,
       coalesce(string_agg(migration || '.' || check_name, ', ') filter (where not ok), 'none') as failing
from checks;
